from pathlib import Path

import yaml

_LOCATORS_PATH = Path(__file__).parent / "locators.yaml"
# Auto-generated by locator_agent.py from a second application's Angular
# templates (the telecom recharge app). Optional -- only merged in if present.
_SECONDARY_LOCATORS_PATH = Path(__file__).parent / "locators_2.yaml"

# The two apps' pages are mostly namespaced apart ("recharge", "recharge
# packs", ...), but locators_2.yaml's "payment" would otherwise silently
# overwrite locators.yaml's own "payment" page (automationexercise.com's
# checkout flow) when merged -- rename it on the way in instead.
_SECONDARY_PAGE_RENAMES = {"payment": "recharge payment"}

_ORDINALS = {
    "first": 0,
    "second": 1,
    "third": 2,
    "fourth": 3,
    "fifth": 4,
}


def _load(path):
    with open(path) as f:
        return yaml.safe_load(f) or {}


def _merge_secondary(data, secondary):
    for page, elements in secondary.items():
        page = _SECONDARY_PAGE_RENAMES.get(page, page)
        if page in data:
            raise ValueError(
                f"locators_2.yaml page '{page}' collides with locators.yaml -- "
                "add it to _SECONDARY_PAGE_RENAMES in config/locators.py"
            )
        data[page] = elements
    return data


def _load_registry():
    data = _load(_LOCATORS_PATH)
    if _SECONDARY_LOCATORS_PATH.exists():
        data = _merge_secondary(data, _load(_SECONDARY_LOCATORS_PATH))
    return data


_DATA = _load_registry()
PAGE_URLS = _DATA["_pages"]


def _ordinal_to_index(value):
    key = value.strip().lower()
    if key in _ORDINALS:
        return _ORDINALS[key]
    return int(key) - 1


def resolve(page, element, value=None):
    """Resolve a (page, element) alias to a selector, filling in {value}/{index} placeholders."""
    try:
        template = _DATA[page][element]
    except KeyError as exc:
        raise KeyError(f"No locator registered for page='{page}', element='{element}'") from exc

    if "{index}" in template:
        return template.format(index=_ordinal_to_index(value))
    if "{value}" in template:
        return template.format(value=value)
    return template
